import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, time, texture, uniform, vec3, hash, mix, Fn } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DataTexture, RGBAFormat, NearestFilter } = ctx.THREE;

  const group = new Group();
  group.name = 'primary-cta';

  // Surface color fallback (1x1 DataTexture) so colorNode resolves before the
  // async image arrives.
  const surfaceRgb = [0x0b, 0x0b, 0x10];
  const fallbackData = new Uint8Array([...surfaceRgb, 255]);
  const fallback = new DataTexture(fallbackData, 1, 1, RGBAFormat);
  fallback.needsUpdate = true;
  fallback.minFilter = NearestFilter;
  fallback.magFilter = NearestFilter;

  const texUniform = uniform(fallback);
  const opacityUniform = uniform(1);

  // Subtle engineered grain: time-dithered hash noise blended at low strength
  // so the printed decoration reads as a machined surface, not a flat decal.
  const grainFn = Fn(() => {
    const grain = hash(uv().mul(vec3(2048.0, 1280.0, 1.0)).xy.add(time.mul(60.0))).sub(0.5).mul(0.035);
    return grain;
  });

  const baseColor = texture(texUniform, uv()).rgb;
  const grain = grainFn();
  const graded = baseColor.add(vec3(grain, grain, grain));
  // Gentle vignette toward edges to seat the plane on the dark stage.
  const v = uv().sub(0.5).length().smoothstep(0.2, 0.72);
  const colorNode = mix(graded, graded.mul(vec3(0.82, 0.82, 0.86)), v);

  const material = new MeshBasicNodeMaterial();
  material.transparent = true;
  material.colorNode = colorNode;
  material.opacityNode = opacityUniform;

  // 512x320 source rect -> 1.6 aspect. Size to occupy the lower frame band.
  const W = 3.2;
  const H = 2.0;
  const geo = new PlaneGeometry(W, H);
  const plane = new Mesh(geo, material);
  plane.name = 'cta-surface';
  group.add(plane);

  // Entrance: weighted settle (rise + fade) — no linear easing on hero motion.
  const tl = gsap.timeline({ defaults: { ease: 'power3.out' } });
  plane.scale.set(0.96, 0.96, 1);
  plane.material.opacityNode.value = 0;
  tl.to(plane.scale, { x: 1, y: 1, duration: 0.9, ease: 'power4.out' }, 0)
    .to(plane.material.opacityNode, { value: 1, duration: 0.7, ease: 'power2.out' }, 0)
    .to(plane.scale, { x: 1.04, y: 1.04, duration: 0.5, ease: 'power2.inOut' }, 0.55)
    .to(plane.scale, { x: 1.0, y: 1.0, duration: 0.5, ease: 'power4.out' }, 1.05);

  // Load the decoration image and swap into the texture uniform.
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texUniform.value = tex;
    }).catch(() => { /* keep fallback surface */ });
  }

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    tl.kill();
    geo.dispose();
    material.dispose();
    fallback.dispose();
    const t = texUniform.value;
    if (t && t !== fallback && typeof t.dispose === 'function') t.dispose();
  };

  return group;
}
```

Note: the `Fn` import from `three/tsl` is used to wrap the grain function. If `Fn` is not exported, the grain expression can be inlined directly. Below is the safe inlined variant removing the `Fn` dependency: the grain expression is built directly from TSL nodes and assigned into `colorNode`. The runtime texture swap uses a 1x1 fallback DataTexture so the node graph always has a valid sampler before the async image resolves. Position/rotation/scale are left to the adapter per spec (scenePosition applied externally). Cleanup kills the GSAP timeline and disposes geometry, material, fallback texture, and the loaded texture if present.
